(function(root){
'use strict';
const encode=s=>new TextEncoder().encode(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function crc(a){let c=-1;for(const b of a){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^-1)>>>0;}
function zip(files){let chunks=[],central=[],offset=0;for(const [name,str] of Object.entries(files)){const n=encode(name),a=encode(str),sum=crc(a),h=new Uint8Array(30+n.length),d=new DataView(h.buffer);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(6,0x800,true);d.setUint32(14,sum,true);d.setUint32(18,a.length,true);d.setUint32(22,a.length,true);d.setUint16(26,n.length,true);h.set(n,30);chunks.push(h,a);const c=new Uint8Array(46+n.length),q=new DataView(c.buffer);q.setUint32(0,0x02014b50,true);q.setUint16(4,20,true);q.setUint16(6,20,true);q.setUint16(8,0x800,true);q.setUint32(16,sum,true);q.setUint32(20,a.length,true);q.setUint32(24,a.length,true);q.setUint16(28,n.length,true);q.setUint32(42,offset,true);c.set(n,46);central.push(c);offset+=h.length+a.length;}
const size=central.reduce((a,c)=>a+c.length,0),end=new Uint8Array(22),d=new DataView(end.buffer);d.setUint32(0,0x06054b50,true);d.setUint16(8,central.length,true);d.setUint16(10,central.length,true);d.setUint32(12,size,true);d.setUint32(16,offset,true);chunks.push(...central,end);const result=new Uint8Array(offset+size+22);let k=0;for(const a of chunks){result.set(a,k);k+=a.length;}return result;}
function threeMF(mesh,project){const s=mesh.settings,title=esc(s.name),vertices=mesh.vertices.map(p=>'<vertex x="'+p[0]+'" y="'+p[1]+'" z="'+p[2]+'"/>').join(''),triangles=mesh.faces.map(t=>'<triangle v1="'+t[0]+'" v2="'+t[1]+'" v3="'+t[2]+'"/>').join('');return zip({
'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/><Default Extension="json" ContentType="application/json"/></Types>',
'_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rel0" Target="/3D/3dmodel.model" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>',
'3D/3dmodel.model':'<?xml version="1.0" encoding="UTF-8"?><model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02"><metadata name="Title">'+title+'</metadata><metadata name="Application">Foldlight Studio</metadata><metadata name="Description">'+(mesh.spiralEnvelope?'Solid envelope: enable spiral vase in slicer, zero top layers.':'Closed mesh. Review wall thickness, dimensions and supports in slicer.')+'</metadata><resources><basematerials id="1"><base name="Preview color" displaycolor="'+s.color.toUpperCase()+'FF"/></basematerials><object id="2" type="model" name="'+title+'" pid="1" pindex="0"><mesh><vertices>'+vertices+'</vertices><triangles>'+triangles+'</triangles></mesh></object></resources><build><item objectid="2"/></build></model>',
'Metadata/foldlight-project.json':JSON.stringify(project,null,2)});}
root.FoldlightExport={threeMF,zip};if(typeof module!=='undefined')module.exports=root.FoldlightExport;
})(globalThis);
